// Wrapper around Pikchr compiled to WebAssembly (see the Makefile).

// The subset of the Emscripten module that we export and use.
interface PikchrModule {
    _pikchr(text: number, cls: number, flags: number, width: number, height: number): number;
    _malloc(size: number): number;
    _free(ptr: number): void;
    stringToNewUTF8(str: string): number;
    UTF8ToString(ptr: number): string;
    getValue(ptr: number, type: "i32"): number;
}

// Generated by Emscripten into build/ and bundled by esbuild.
const createPikchr: () => Promise<PikchrModule> = require("../build/pikchr-wasm.js");

// From pikchr.c: report errors as plain text rather than HTML.
const PIKCHR_PLAINTEXT_ERRORS = 0x0001;

// SPECK compiles diagrams with the same class (see `process_pikchr` in `src/speck.lua`).
const SVG_CLASS = "pikchr";

export type RenderResult = { ok: true; svg: string } | { ok: false; error: string };

export class Pikchr {
    private constructor(private readonly module: PikchrModule) { }

    static async load(): Promise<Pikchr> {
        return new Pikchr(await createPikchr());
    }

    render(source: string): RenderResult {
        try {
            return this.compile(source);
        } catch (e) {
            // The WebAssembly module aborted, it cannot be used anymore.
            return { ok: false, error: `Pikchr crashed: ${e}` };
        }
    }

    private compile(source: string): RenderResult {
        const m = this.module;
        const text = m.stringToNewUTF8(source);
        const cls = m.stringToNewUTF8(SVG_CLASS);
        const size = m._malloc(8);

        const out = m._pikchr(text, cls, PIKCHR_PLAINTEXT_ERRORS, size, size + 4);
        const result = out ? m.UTF8ToString(out) : "Out of memory";
        // Pikchr reports a width of -1 when there is an error.
        const ok = out !== 0 && m.getValue(size, "i32") >= 0;

        m._free(text);
        m._free(cls);
        m._free(size);
        m._free(out);

        return ok ? { ok: true, svg: result } : { ok: false, error: result };
    }
}
